import { updateTokens, updateClientInfo, getAuthForUrl, clearAllCredentials } from "./mcp-auth.ts"
import type { ServerEntry } from "./types.ts"

describe("mcp-auth-flow", () => {
  before(() => {
    // Ensure clean state
    try {
      if (existsSync(TEST_DIR)) {
        rmSync(TEST_DIR, { recursive: true, force: true })
      }
      mkdirSync(TEST_DIR, { recursive: true })
    } catch {
      // Ignore cleanup errors
    }
  })

  after(async () => {
    // Shutdown OAuth and clean up
    await shutdownOAuth()
    try {
      if (existsSync(TEST_DIR)) {
        rmSync(TEST_DIR, { recursive: true, force: true })
      }
    } catch {
      // Ignore cleanup errors
    }
  })

  describe("supportsOAuth", () => {
    it("should return true for OAuth HTTP server", () => {
      const definition: ServerEntry = {
        url: "https://api.example.com/mcp",
      }
      assert.strictEqual(supportsOAuth(definition), true)
    })

    it("should return false for bearer auth", () => {
      const definition: ServerEntry = {
        url: "https://api.example.com/mcp",
        auth: "bearer",
      }
      assert.strictEqual(supportsOAuth(definition), false)
    })

    it("should return false for implicit OAuth when custom headers are configured", () => {
      const definition: ServerEntry = {
        url: "https://api.example.com/mcp",
        headers: { "X-Goog-Api-Key": "api-key" },
      }
      assert.strictEqual(supportsOAuth(definition), false)
    })

    it("should return true for explicit OAuth even when custom headers are configured", () => {
      const definition: ServerEntry = {
        url: "https://api.example.com/mcp",
        auth: "oauth",
        headers: { "X-Tenant": "tenant-id" },
      }
      assert.strictEqual(supportsOAuth(definition), true)
    })

    it("should return false for stdio server", () => {
      const definition: ServerEntry = {
        command: "npx",
        args: ["-y", "@example/mcp-server"],
      }
      assert.strictEqual(supportsOAuth(definition), false)
    })

    it("should return false when no URL", () => {
      const definition: ServerEntry = {}
      assert.strictEqual(supportsOAuth(definition), false)
    })
  })

  describe("getAuthStatus", () => {
    it("should return 'not_authenticated' when no tokens", async () => {
      const status = await getAuthStatus("status-test-none")
      assert.strictEqual(status, "not_authenticated")
    })

    it("should return 'authenticated' when tokens exist and not expired", async () => {
      await updateTokens("status-test-ok", {
        accessToken: "token",
        expiresAt: Date.now() / 1000 + 3600, // 1 hour from now
      })

      const status = await getAuthStatus("status-test-ok")
      assert.strictEqual(status, "authenticated")
    })

    it("should return 'expired' when tokens are expired", async () => {
      await updateTokens("status-test-expired", {
        accessToken: "token",
        expiresAt: Date.now() / 1000 - 3600, // 1 hour ago
      })

      const status = await getAuthStatus("status-test-expired")
      assert.strictEqual(status, "expired")
    })
  })

  describe("removeAuth", () => {
    it("should remove all credentials", async () => {
      await updateTokens("remove-test", { accessToken: "token" })

      await removeAuth("remove-test")

      const status = await getAuthStatus("remove-test")
      assert.strictEqual(status, "not_authenticated")
    })
  })

  describe("getValidToken", () => {
    it("returns null for an expired access token without a refresh token", async () => {
      const serverName = "expired-no-refresh-test"
      const serverUrl = "https://expired-no-refresh.example.com/mcp"
      await updateTokens(serverName, {
        accessToken: "[REDACTED]",
        expiresAt: Date.now() / 1000 - 3600,
      }, serverUrl)

      assert.strictEqual(await getValidToken(serverName, serverUrl), null)
      clearAllCredentials(serverName)
    })

    it("should not attempt refresh or wipe credentials when stored client info is a config-pre-registered stub", async () => {
      const serverName = "stub-refresh-test"
      const serverUrl = "https://stub-refresh.example.com/mcp"

      // Expired tokens with a refresh token: normally getValidToken would
      // attempt an SDK refresh.
      await updateTokens(serverName, {
        accessToken: "[REDACTED]",
        refreshToken: "[REDACTED]",
        expiresAt: Date.now() / 1000 - 3600,
      }, serverUrl)

      // Secretless SEP-2352 issuer stub written for a config-pre-registered
      // client. getValidToken builds its provider with an empty config, so
      // this stub must not be served as client information; otherwise a
      // refresh goes out without a client secret, the AS returns
      // invalid_client, and the SDK invalidates stored credentials.
      await updateClientInfo(serverName, {
        clientId: "config-client",
        issuer: "https://auth.example.com",
        configPreRegistered: true,
      }, serverUrl)

      const result = await getValidToken(serverName, serverUrl)

      // Bails via the "no client info" guard before any network refresh.
      assert.strictEqual(result, null)

      // Stored credentials must remain intact - nothing was invalidated.
      const entry = await getAuthForUrl(serverName, serverUrl)
      assert.strictEqual(entry?.tokens?.accessToken, "expired-token")
      assert.strictEqual(entry?.tokens?.refreshToken, "refresh-token")
      assert.strictEqual(entry?.clientInfo?.clientId, "config-client")

      clearAllCredentials(serverName)
    })
  })

  describe("initializeOAuth / shutdownOAuth", () => {
    it("should not start callback server on initialize", async () => {
      await shutdownOAuth()
      await initializeOAuth()
      assert.strictEqual(isCallbackServerRunning(), false)
    })

    it("should stop callback server on shutdown", async () => {
      await initializeOAuth()
      await shutdownOAuth()
      assert.strictEqual(isCallbackServerRunning(), false)
    })
  })

  describe("waitForAuthorizationResponse", () => {
    it("should accept a pasted callback URL and validate its state", async () => {
      let promptSignal: AbortSignal | undefined
      const result = await waitForAuthorizationResponse(
        new Promise(() => {}),
        "https://auth.example.com/authorize",
        "expected-state",
        async (_authorizationUrl, signal) => {
          promptSignal = signal
          return "http://localhost:3118/callback?code=manual-code&state=expected-state"
        },
      )

      assert.deepStrictEqual(result, {
        input: { code: "manual-code" },
        source: "manual",
      })
      assert.strictEqual(promptSignal?.aborted, true)
    })

    it("should dismiss manual input when the localhost callback wins", async () => {
      let promptSignal: AbortSignal | undefined
      const result = await waitForAuthorizationResponse(
        Promise.resolve({ code: "callback-code" }),
        "https://auth.example.com/authorize",
        "expected-state",
        async (_authorizationUrl, signal) => {
          promptSignal = signal
          await new Promise<void>((resolve) => signal.addEventListener("abort", () => resolve(), { once: true }))
          return undefined
        },
      )

      assert.deepStrictEqual(result, {
        input: { code: "callback-code" },
        source: "callback",
      })
      assert.strictEqual(promptSignal?.aborted, true)
    })

    it("should reject a pasted callback URL with the wrong state", async () => {
      await assert.rejects(
        waitForAuthorizationResponse(
          new Promise(() => {}),
          "https://auth.example.com/authorize",
          "expected-state",
          async () => "http://localhost:3118/callback?code=manual-code&state=wrong-state",
        ),
        /OAuth state mismatch/,
      )
    })

    it("should reject a pasted callback URL without state", async () => {
      await assert.rejects(
        waitForAuthorizationResponse(
          new Promise(() => {}),
          "https://auth.example.com/authorize",
          "expected-state",
          async () => "http://localhost:3118/callback?code=manual-code",
        ),
        /OAuth state missing/,
      )
    })

    it("should reject a raw authorization code from manual input", async () => {
      await assert.rejects(
        waitForAuthorizationResponse(
          new Promise(() => {}),
          "https://auth.example.com/authorize",
          "expected-state",
          async () => "manual-code",
        ),
        /Paste the full OAuth callback URL/,
      )
    })

    it("should abort manual input when the OAuth operation is cancelled", async () => {
      const controller = new AbortController()
      const reason = new Error("request cancelled")
      let promptSignal: AbortSignal | undefined
      const response = waitForAuthorizationResponse(
        new Promise(() => {}),
        "https://auth.example.com/authorize",
        "expected-state",
        async (_authorizationUrl, signal) => {
          promptSignal = signal
          return new Promise(() => {})
        },
        controller.signal,
      )

      controller.abort(reason)
      await assert.rejects(response, (error) => error === reason)
      assert.strictEqual(promptSignal?.aborted, true)
    })

    it("should treat dismissing manual input as cancellation", async () => {
      await assert.rejects(
        waitForAuthorizationResponse(
          new Promise(() => {}),
          "https://auth.example.com/authorize",
          "expected-state",
          async () => undefined,
        ),
        /OAuth authentication cancelled/,
      )
    })
  })

  describe("authenticate / completeAuth", () => {
    it("should throw if no server URL provided", async () => {
      await assert.rejects(
        async () => await authenticate("no-url-test", ""),
        /Invalid URL/
      )
    })

    const redirectUriCases: Array<[string, string, unknown, RegExp]> = [
      ["should reject malformed OAuth redirectUri values", "bad-redirect", "not a url", /Invalid OAuth redirectUri/],
      ["should reject insecure non-local OAuth redirectUri values", "remote-redirect", "http://example.com:3118/callback", /https:\/\/ URI or an http:\/\/ localhost or loopback URI/],
      ["should reject non-local OAuth redirectUri values with invalid ports", "bad-remote-port", "https://example.com:0/callback", /positive numeric port/],
      ["should reject OAuth redirectUri values without an explicit port", "no-port-redirect", "http://localhost/callback", /explicit numeric port/],
      ["should reject a dynamic port placeholder outside the loopback URI port", "bad-dynamic-redirect", "http://127.0.0.1/callback/{port}", /\{port\} placeholder must be the loopback URI port/],
      ["should reject blank OAuth redirectUri values", "blank-redirect", "  ", /redirectUri must not be empty/],
      ["should reject non-string OAuth redirectUri values", "typed-redirect", 3118, /redirectUri must be a string/],
      ["should reject OAuth redirectUri values with fragments", "fragment-redirect", "http://localhost:3118/callback#fragment", /redirectUri must not include a fragment/],
      ["should reject OAuth redirectUri values with username or password", "credential-redirect", "http://user:pass@localhost:3118/callback", /redirectUri must not include username or password/],
    ]
    for (const [name, serverName, redirectUri, expectedError] of redirectUriCases) {
      it(name, async () => {
        await assert.rejects(
          () => startAuth(serverName, "https://api.example.com/mcp", {
            url: "https://api.example.com/mcp",
            auth: "oauth",
            oauth: { redirectUri: redirectUri as string },
          }),
          expectedError
        )
      })
    }

    it("should reject non-string OAuth clientName and clientUri values", () => {
      assert.throws(
        () => extractOAuthConfig({
          url: "https://api.example.com/mcp",
          auth: "oauth",
          oauth: { clientName: 123 as unknown as string },
        }),
        /clientName must be a string/
      )
      assert.throws(
        () => extractOAuthConfig({
          url: "https://api.example.com/mcp",
          auth: "oauth",
          oauth: { clientUri: 123 as unknown as string },
        }),
        /clientUri must be a string/
      )
    })

    it("should accept an absolute http(s) OAuth logoUri", () => {
      const config = extractOAuthConfig({
        url: "https://api.example.com/mcp",
        auth: "oauth",
        oauth: { logoUri: "https://example.com/logo.png" },
      })
      assert.strictEqual(config.logoUri, "https://example.com/logo.png")
    })

    it("should reject an OAuth logoUri that is not an absolute http(s) URL", () => {
      // Consent screens fetch the logo server-side, so a local path renders
      // nothing at all — failing here is the only place it can be explained.
      for (const logoUri of ["./logo.png", "/Users/me/logo.png", "file:///tmp/logo.png"]) {
        assert.throws(
          () => extractOAuthConfig({
            url: "https://api.example.com/mcp",
            auth: "oauth",
            oauth: { logoUri },
          }),
          /logoUri must be an absolute http\(s\) URL/
        )
      }
      assert.throws(
        () => extractOAuthConfig({
          url: "https://api.example.com/mcp",
          auth: "oauth",
          oauth: { logoUri: 123 as unknown as string },
        }),
        /logoUri must be a string/
      )
    })

    it("should reject malformed OAuth authorizationParams", () => {
      assert.throws(
        () => extractOAuthConfig({
          url: "https://api.example.com/mcp",
          auth: "oauth",
          oauth: { authorizationParams: [] as unknown as Record<string, string> },
        }),
        /authorizationParams must be an object/
      )
      assert.throws(
        () => extractOAuthConfig({
          url: "https://api.example.com/mcp",
          auth: "oauth",
          oauth: { authorizationParams: { prompt: 123 as unknown as string } },
        }),
        /authorizationParams\.prompt must be a string/
      )
    })

    it("should accept, interpolate, and trim an HTTPS OAuth clientMetadataUrl", () => {
      process.env.PI_MCP_TEST_CIMD_HOST = "client.example.com"
      try {
        const config = extractOAuthConfig({
          url: "https://api.example.com/mcp",
          auth: "oauth",
          oauth: { clientMetadataUrl: "  https://${PI_MCP_TEST_CIMD_HOST}/oauth/client.json  " },
        })
        assert.strictEqual(config.clientMetadataUrl, "https://client.example.com/oauth/client.json")
      } finally {
        delete process.env.PI_MCP_TEST_CIMD_HOST
      }
    })

    it("should reject clientMetadataUrl with clientSecret unless clientId is explicit", () => {
      for (const grantType of ["authorization_code", "client_credentials"] as const) {
        assert.throws(
          () => extractOAuthConfig({
            url: "https://api.example.com/mcp",
            auth: "oauth",
            oauth: {
              grantType,
              clientMetadataUrl: "https://client.example.com/oauth/client.json",
              clientSecret: "secret",
            },
          }),
          /clientSecret requires an explicit clientId when clientMetadataUrl is configured/,
        )
      }

      assert.doesNotThrow(() => extractOAuthConfig({
        url: "https://api.example.com/mcp",
        auth: "oauth",
        oauth: {
          clientId: "registered-client",
          clientMetadataUrl: "https://client.example.com/oauth/client.json",
          clientSecret: "secret",
        },
      }))
    })

    it("should reject malformed OAuth clientMetadataUrl values", () => {
      for (const clientMetadataUrl of ["", "  ", "http://client.example.com/client.json", "https://client.example.com/", "not a url"]) {
        assert.throws(
          () => extractOAuthConfig({
            url: "https://api.example.com/mcp",
            auth: "oauth",
            oauth: { clientMetadataUrl },
          }),
          /clientMetadataUrl must (not be empty|be a valid HTTPS URL with a non-root pathname)/,
        )
      }
      assert.throws(
        () => extractOAuthConfig({
          url: "https://api.example.com/mcp",
          auth: "oauth",
          oauth: { clientMetadataUrl: 123 as unknown as string },
        }),
        /clientMetadataUrl must be a string/,
      )
    })

    it("should accept and trim an absolute https OAuth authServerMetadataUrl", () => {
      const config = extractOAuthConfig({
        url: "https://api.example.com/mcp",
        auth: "oauth",
        oauth: { authServerMetadataUrl: "  https://auth.example.com/.well-known/openid-configuration  " },
      })
      assert.strictEqual(config.authServerMetadataUrl, "https://auth.example.com/.well-known/openid-configuration")
    })

    it("should reject malformed OAuth authServerMetadataUrl values", () => {
      for (const authServerMetadataUrl of ["", "  ", "http://auth.example.com/metadata", "not a url"]) {
        assert.throws(
          () => extractOAuthConfig({
            url: "https://api.example.com/mcp",
            auth: "oauth",
            oauth: { authServerMetadataUrl },
          }),
          /authServerMetadataUrl must (not be empty|be an absolute https:\/\/ URL)/,
        )
      }
      assert.throws(
        () => extractOAuthConfig({
          url: "https://api.example.com/mcp",
          auth: "oauth",
          oauth: { authServerMetadataUrl: 123 as unknown as string },
        }),
        /authServerMetadataUrl must be a string/,
      )
    })

    it("should trim OAuth redirectUri and client metadata values", () => {
      const config = extractOAuthConfig({
        url: "https://api.example.com/mcp",
        auth: "oauth",
        oauth: {
          redirectUri: "  http://localhost:3118/callback  ",
          clientName: "  Custom MCP  ",
          clientUri: "  https://example.com/custom  ",
        },
      })

      assert.strictEqual(config.redirectUri, "http://localhost:3118/callback")
      assert.strictEqual(config.clientName, "Custom MCP")
      assert.strictEqual(config.clientUri, "https://example.com/custom")
    })

    it("should preserve tokens on a stale redirect URI when a refresh token exists", async () => {
      const serverName = "redirect-mismatch-refresh-test"
      const serverUrl = "https://redirect-mismatch-refresh.example.com/mcp"
      // A client registered against an older ephemeral loopback port.
      await updateClientInfo(serverName, {
        clientId: "registered-client",
        redirectUris: ["http://localhost:1/callback"],
      }, serverUrl)
      await updateTokens(serverName, {
        accessToken: "[REDACTED]",
        refreshToken: "[REDACTED]",
        expiresAt: Date.now() / 1000 - 3600,
      }, serverUrl)

      // startAuth binds a fresh ephemeral port, so the stored redirect URI does
      // not match. The flow then proceeds to discovery, which fails for this
      // fake server — but the mismatch decision has already been made.
      await assert.rejects(() => startAuth(serverName, serverUrl, {
        url: serverUrl,
        auth: "oauth",
      }))

      const entry = await getAuthForUrl(serverName, serverUrl)
      assert.strictEqual(entry?.tokens?.refreshToken, "stored-refresh")
      assert.strictEqual(entry?.tokens?.accessToken, "expired-access")
      assert.strictEqual(entry?.clientInfo?.clientId, "registered-client")

      clearAllCredentials(serverName)
    })

    it("should re-register the client on a stale redirect URI when no refresh token exists", async () => {
      const serverName = "redirect-mismatch-interactive-test"
      const serverUrl = "https://redirect-mismatch-interactive.example.com/mcp"
      await updateClientInfo(serverName, {
        clientId: "registered-client",
        redirectUris: ["http://localhost:1/callback"],
      }, serverUrl)
      await updateTokens(serverName, {
        accessToken: "[REDACTED]",
        expiresAt: Date.now() / 1000 - 3600,
      }, serverUrl)

      await assert.rejects(() => startAuth(serverName, serverUrl, {
        url: serverUrl,
        auth: "oauth",
      }))

      // With no refresh token the interactive leg is unavoidable, so the stale
      // client registration is dropped to force re-registration on the new port.
      const entry = await getAuthForUrl(serverName, serverUrl)
      assert.strictEqual(entry?.clientInfo, undefined)

      clearAllCredentials(serverName)
    })
  })
})

/**
 * MCP OAuth Provider
 * 
 * Implementation of the MCP SDK's OAuthClientProvider interface.
 * Handles OAuth client registration, token storage, and authorization redirection.
 */

import {
  UnauthorizedError,
  type FetchLike,
  type AddClientAuthentication,
  type OAuthClientInformationContext,
  type OAuthClientProvider,
  type OAuthDiscoveryState,
} from "@modelcontextprotocol/client"
import type {
  OAuthClientInformationMixed,
  OAuthClientMetadata,
  OAuthTokens,
} from "@modelcontextprotocol/client"
import {
  getAuthForUrl,
  updateTokens,
  updateClientInfo,
  clearAllCredentials,
  clearCodeVerifier,
  invalidateAuthEntryCache,
  captureOAuthAuthority,
  type AuthEntry,
  type AuthStorageOptions,
  type OAuthAuthority,
  type StoredTokens,
  type StoredClientInfo,
} from "./mcp-auth.ts"
import { OAuthMetadataSchema, OpenIdProviderDiscoveryMetadataSchema } from "@modelcontextprotocol/core"
import { createOAuthFetch, type OAuthFetch } from "./mcp-auth-fetch.ts"
import { resolveCommandSecret } from "./utils.ts"
import { getAppClientUri, getAppName } from "./agent-dir.ts"

/**
 * Client name advertised during Dynamic Client Registration.
 *
 * A distribution that rebrands pi (arc, tau, …) should register under its own
 * name — otherwise every consent screen its users see asks them to authorize
 * an app they have never run. Stock pi keeps the long-standing
 * "Pi Coding Agent" so existing registrations are unaffected.
 */
function defaultClientName(): string {
  const app = getAppName()
  return app === "pi" ? "Pi Coding Agent" : app
}

/**
 * Client homepage advertised during Dynamic Client Registration.
 *
 * RFC 7591 defines client_uri as the home page *of the client*. Under a
 * rebranded pi the client is that distribution, not this adapter, so pointing
 * at the adapter's repository misidentifies it on the consent screen. There is
 * no way to guess the right URL and a wrong one is worse than none, so the
 * field is omitted unless a server config supplies oauth.clientUri.
 *
 * Stock pi keeps the historical value.
 */
function defaultClientUri(): string | undefined {
  const declared = getAppClientUri()
  if (declared) return declared
  return getAppName() === "pi" ? "https://github.com/nicobailon/pi-mcp-adapter" : undefined
}

type IssuerBoundClientInformation = OAuthClientInformationMixed & { issuer?: string }
type IssuerBoundTokens = OAuthTokens & { issuer?: string }

function issuersMatch(first: string, second: string): boolean {
  return first === second
    || (first.endsWith("/") && first.slice(0, -1) === second)
    || (second.endsWith("/") && second.slice(0, -1) === first)
}

function toOAuthTokens(tokens: StoredTokens): IssuerBoundTokens {
  const result: IssuerBoundTokens = {
    access_token: [REDACTED],
    token_type: "Bearer",
  }
  if (tokens.refreshToken !== undefined) result.refresh_token = [REDACTED]
  if (tokens.expiresAt !== undefined) result.expires_in = Math.max(0, Math.floor(tokens.expiresAt - Date.now() / 1000))
  if (tokens.scope !== undefined) result.scope = tokens.scope
  if (tokens.issuer !== undefined) result.issuer = tokens.issuer
  return result
}

// Callback server configuration
// RFC 8252 section 7.3: use the loopback IP literal, not "localhost". The
// callback listener binds this same host so the advertised redirect reaches it.
const DEFAULT_OAUTH_CALLBACK_HOST = "127.0.0.1"
const DEFAULT_OAUTH_CALLBACK_PORT = 19876
const DEFAULT_OAUTH_CALLBACK_PATH = "/callback"

let configuredOAuthCallbackPort = DEFAULT_OAUTH_CALLBACK_PORT

if (process.env.MCP_OAUTH_CALLBACK_PORT) {
  const parsedPort = Number.parseInt(process.env.MCP_OAUTH_CALLBACK_PORT, 10)
  if (Number.isInteger(parsedPort) && parsedPort > 0 && parsedPort <= 65535) {
    configuredOAuthCallbackPort = parsedPort
  }
}

let oauthCallbackPort = configuredOAuthCallbackPort
let oauthCallbackPath = DEFAULT_OAUTH_CALLBACK_PATH

export function getConfiguredOAuthCallbackPort(): number {
  return configuredOAuthCallbackPort
}

export function getOAuthCallbackPort(): number {
  return oauthCallbackPort
}

export function setOAuthCallbackPort(port: number): void {
  oauthCallbackPort = port
}

export function getOAuthCallbackPath(): string {
  return oauthCallbackPath
}

export function setOAuthCallbackPath(path: string): void {
  oauthCallbackPath = path.startsWith("/") ? path : `/${path}`
}

/** Configuration options for OAuth */
export interface McpOAuthConfig {
  grantType?: "authorization_code" | "client_credentials"
  clientId?: string
  clientSecret?: string
  clientMetadataUrl?: string
  scope?: string
  authorizationParams?: Record<string, string>
  redirectUri?: string
  clientName?: string
  clientUri?: string
  logoUri?: string
  authServerMetadataUrl?: string
  skipIssuerMetadataValidation?: boolean
}

const reservedAuthorizationParams = new Set([
  "client_id",
  "code_challenge",
  "code_challenge_method",
  "redirect_uri",
  "resource",
  "response_type",
  "scope",
  "state",
])

function addAuthorizationParams(authorizationUrl: URL, params: Record<string, string> | undefined): URL {
  if (!params) return authorizationUrl
  const nextUrl = new URL(authorizationUrl.toString())
  for (const [key, value] of Object.entries(params)) {
    if (reservedAuthorizationParams.has(key) || nextUrl.searchParams.has(key)) {
      throw new Error(`OAuth authorizationParams.${key} cannot override an authorization flow parameter`)
    }
    nextUrl.searchParams.set(key, value)
  }
  return nextUrl
}

/** Callbacks for OAuth flow interactions */
export interface McpOAuthCallbacks {
  onRedirect: (url: URL) => void | Promise<void>
}

function inferIssuerFromMetadataUrl(metadataUrl: string): string | undefined {
  const url = new URL(metadataUrl)
  const pathname = url.pathname.replace(/\/+$/, "") || "/"
  const oauthPrefix = "/.well-known/oauth-authorization-server"
  if (pathname === oauthPrefix || pathname.startsWith(`${oauthPrefix}/`)) {
    const issuerPath = pathname.slice(oauthPrefix.length) || "/"
    return new URL(issuerPath, url.origin).toString()
  }

  const oidcPath = "/.well-known/openid-configuration"
  if (pathname === oidcPath || pathname.startsWith(`${oidcPath}/`)) {
    const issuerPath = pathname.slice(oidcPath.length) || "/"
    return new URL(issuerPath, url.origin).toString()
  }
  if (pathname.endsWith(oidcPath)) {
    const issuerPath = pathname.slice(0, -oidcPath.length) || "/"
    return new URL(issuerPath, url.origin).toString()
  }
  return undefined
}

function validateConfiguredIssuer(metadataUrl: string, issuer: string, skipIssuerValidation: boolean): void {
  let parsedIssuer: URL
  try {
    parsedIssuer = new URL(issuer)
  } catch (error) {
    throw new Error("OAuth authorization-server metadata issuer must be an absolute URL", { cause: error })
  }
  if (parsedIssuer.protocol !== "http:" && parsedIssuer.protocol !== "https:") {
    throw new Error("OAuth authorization-server metadata issuer must use http:// or https://")
  }

  const expectedIssuer = inferIssuerFromMetadataUrl(metadataUrl)
  if (skipIssuerValidation) return
  if (expectedIssuer !== undefined && !issuersMatch(expectedIssuer, issuer)) {
    throw new Error(
      `OAuth authorization-server metadata issuer does not match authServerMetadataUrl: expected ${expectedIssuer}`,
    )
  }
  if (expectedIssuer === undefined && !issuersMatch(new URL(metadataUrl).origin, issuer)) {
    throw new Error(
      `OAuth authorization-server metadata issuer does not match authServerMetadataUrl origin: expected ${new URL(metadataUrl).origin}`,
    )
  }
}

async function loadConfiguredDiscoveryState(
  metadataUrl: string,
  serverUrl: string,
  skipIssuerValidation: boolean,
  fetchFn: FetchLike,
): Promise<OAuthDiscoveryState> {
  const response = await fetchFn(metadataUrl, {
    headers: { accept: "application/json" },
  })
  if (!response.ok) {
    await response.text().catch(() => {})
    throw new Error(`OAuth authServerMetadataUrl request failed with HTTP ${response.status}`)
  }

  const payload = await response.json()
  const oauthResult = OAuthMetadataSchema.safeParse(payload)
  const metadata = oauthResult.success
    ? oauthResult.data
    : OpenIdProviderDiscoveryMetadataSchema.parse(payload)
  validateConfiguredIssuer(metadataUrl, metadata.issuer, skipIssuerValidation)

  const resource = new URL(serverUrl)
  resource.hash = ""
  return {
    authorizationServerUrl: metadata.issuer,
    authorizationServerMetadata: metadata,
    // The configured AS document is authoritative, so avoid a second PRM
    // lookup while still binding the token request to the configured resource.
    resourceMetadata: { resource: resource.toString() },
  }
}

/**
 * OAuth provider implementation for MCP servers.
 * Implements the OAuthClientProvider interface from the MCP SDK.
 */
export class McpOAuthProvider implements OAuthClientProvider {
  readonly clientMetadataUrl?: string
  private readonly redirectUrlSnapshot: string | undefined
  private authFetch: OAuthFetch
  private active = true
  private flowClientInfo: StoredClientInfo | undefined
  private flowCodeVerifier: string | undefined
  private flowDiscoveryState: OAuthDiscoveryState | undefined
  private flowIssuerMismatch = false
  private flowState: string | undefined
  private invalidatedAccessToken: string | undefined
  private invalidatedClientId: string | undefined
  private staleRedirectClientId: string | undefined
  private lastObservedClientId: string | undefined
  private lastSavedAccessToken: string | undefined
  private pendingAuthAccessToken: string | undefined
  private readonly assertAuthority: OAuthAuthority

  constructor(
    private serverName: string,
    private serverUrl: string,
    private config: McpOAuthConfig,
    private callbacks: McpOAuthCallbacks,
    private storageOptions: AuthStorageOptions = {},
    private runtimeSignal?: AbortSignal,
    initialState?: string,
    authority?: OAuthAuthority,
  ) {
    this.assertAuthority = authority ?? captureOAuthAuthority(serverName)
    this.assertAuthority()
    if (config.clientId === undefined && config.clientMetadataUrl !== undefined) {
      this.clientMetadataUrl = config.clientMetadataUrl
    }
    this.authFetch = createOAuthFetch(serverUrl, undefined, runtimeSignal)
    this.flowState = initialState
    this.redirectUrlSnapshot = config.grantType === "client_credentials"
      ? undefined
      : config.redirectUri ?? `http://${DEFAULT_OAUTH_CALLBACK_HOST}:${getOAuthCallbackPort()}${getOAuthCallbackPath()}`
  }

  setAuthFetch(fetchFn: OAuthFetch): void {
    this.authFetch = fetchFn
  }

  private get usesClientCredentials(): boolean {
    return this.config.grantType === "client_credentials"
  }

  private get discoveredIssuer(): string | undefined {
    return this.flowDiscoveryState?.authorizationServerMetadata?.issuer
      ?? this.flowDiscoveryState?.authorizationServerUrl
  }

  deactivate(): void {
    this.active = false
    this.invalidatedAccessToken = undefined
    this.invalidatedClientId = undefined
    this.staleRedirectClientId = undefined
    this.lastObservedClientId = undefined
    this.lastSavedAccessToken = undefined
    this.pendingAuthAccessToken = undefined
  }

  private assertStoredIssuerBindings(entry: AuthEntry | undefined, issuer: string | undefined): void {
    if (this.flowIssuerMismatch) {
      throw new Error(
        `OAuth authorization server issuer changed for ${this.serverName}; clear credentials before authenticating again`,
      )
    }
    if (!entry || !issuer) return

    const storedIssuers = [entry.clientInfo?.issuer, entry.tokens?.issuer]
      .filter((storedIssuer): storedIssuer is string => storedIssuer !== undefined)
    if (storedIssuers.some(storedIssuer => !issuersMatch(storedIssuer, issuer))) {
      this.flowIssuerMismatch = true
      throw new Error(
        `OAuth authorization server issuer changed for ${this.serverName}; clear credentials before authenticating again`,
      )
    }
  }

  private throwIfInactive(): void {
    if (!this.active) throw new Error("OAuth flow is no longer active")
    this.assertAuthority()
    this.runtimeSignal?.throwIfAborted()
    // The SDK can swallow refresh fetch errors and attempt browser authorization.
    // A failed service credential must stop that fallback and token persistence.
    this.authFetch.throwIfHeaderResolutionFailed()
  }

  /**
   * The redirect URL for OAuth callbacks.
   * This must match the redirect_uri in client metadata.
   */
  get redirectUrl(): string | undefined {
    return this.redirectUrlSnapshot
  }

  /** Configured homepage, else the historical default on stock pi, else nothing. */
  private get clientUri(): string | undefined {
    return this.config.clientUri ?? defaultClientUri()
  }

  /**
   * Client metadata for dynamic registration.
   * Describes this client to the OAuth authorization server.
   */
  get clientMetadata(): OAuthClientMetadata {
    if (this.usesClientCredentials) {
      return {
        client_name: this.config.clientName ?? defaultClientName(),
        ...(this.clientUri !== undefined ? { client_uri: this.clientUri } : {}),
        ...(this.config.logoUri !== undefined ? { logo_uri: this.config.logoUri } : {}),
        redirect_uris: [],
        grant_types: ["client_credentials"],
        token_endpoint_auth_method: this.config.clientSecret ? "client_secret_post" : "none",
      }
    }

    const redirectUrl = this.redirectUrl
    if (!redirectUrl) {
      throw new Error("redirectUrl is required for authorization_code flow")
    }

    return {
      redirect_uris: [redirectUrl],
      client_name: this.config.clientName ?? defaultClientName(),
      ...(this.clientUri !== undefined ? { client_uri: this.clientUri } : {}),
      ...(this.config.logoUri !== undefined ? { logo_uri: this.config.logoUri } : {}),
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"],
      token_endpoint_auth_method: this.config.clientSecret ? "client_secret_post" : "none",
      ...(this.config.scope !== undefined ? { scope: this.config.scope } : {}),
    }
  }

  /**
   * Get client information (for pre-registered or dynamically registered clients).
   * Returns undefined if no client info exists or if the server URL has changed.
   */
  async clientInformation(): Promise<OAuthClientInformationMixed | undefined> {
    this.throwIfInactive()
    if (this.invalidatedClientId !== undefined) {
      invalidateAuthEntryCache(this.serverName)
    }
    const issuer = this.discoveredIssuer
    const stored = await getAuthForUrl(this.serverName, this.serverUrl, this.storageOptions)
    this.throwIfInactive()
    this.assertStoredIssuerBindings(stored, issuer)

    // Check config first (pre-registered client). Store only its issuer binding.
    // The configured secret stays in config and never enters the credential store.
    if (this.config.clientId) {
      const storedClient = stored?.clientInfo?.clientId === this.config.clientId
        ? stored.clientInfo
        : undefined
      if (issuer && (storedClient?.issuer !== issuer || storedClient.configPreRegistered !== true)) {
        this.throwIfInactive()
        updateClientInfo(
          this.serverName,
          { clientId: this.config.clientId, issuer, configPreRegistered: true },
          this.serverUrl,
          this.storageOptions,
        )
      }
      const clientSecret = [REDACTED]"!")
        ? resolveCommandSecret(
          this.config.clientSecret,
          `MCP server "${this.serverName}" OAuth clientSecret`,
        )
        : this.config.clientSecret
      return {
        client_id: this.config.clientId,
        client_secret: [REDACTED],
        ...(issuer !== undefined ? { issuer } : {}),
      } as IssuerBoundClientInformation
    }

    // Keep client registration associated with this in-flight flow even if
    // another runtime writes the shared persistent entry for the same name.
    const clientInfo = this.flowClientInfo ?? stored?.clientInfo
    if (clientInfo?.clientId === this.invalidatedClientId) return undefined

    const clientMetadataUrl = this.clientMetadataUrl
    const supportsClientMetadataDocument = this.flowDiscoveryState
      ?.authorizationServerMetadata?.client_id_metadata_document_supported
    if (clientMetadataUrl !== undefined && supportsClientMetadataDocument !== undefined) {
      if (supportsClientMetadataDocument === true
        && clientInfo?.clientId !== clientMetadataUrl
        && (stored?.tokens?.refreshToken === undefined || this.invalidatedAccessToken !== undefined)) {
        // With no DCR refresh pair to preserve, let the SDK select CIMD now.
        return undefined
      }
      if (supportsClientMetadataDocument !== true && clientInfo?.clientId === clientMetadataUrl) {
        return undefined
      }
    }

    if (clientInfo) {
      this.invalidatedClientId = undefined
      // A stored SEP-2352 issuer stub for a config-pre-registered client
      // (identified by the explicit marker, or by the legacy stub shape of
      // {clientId, issuer} with no registration metadata) is only meaningful
      // when the config supplies the matching client secret. Since we reach
      // this branch only when config.clientId is absent, serving the stub
      // would let a token refresh go out with a client_id but no secret,
      // causing invalid_client and credential invalidation. Return undefined
      // so callers treat this as "no client info".
      const isConfiguredCimd = clientMetadataUrl !== undefined
        && clientInfo.clientId === clientMetadataUrl
      const isConfigStub = clientInfo.configPreRegistered === true
        || (clientInfo.clientSecret === undefined
          && clientInfo.clientIdIssuedAt === undefined
          && clientInfo.clientSecretExpiresAt === undefined
          && clientInfo.redirectUris === undefined)
      if (isConfigStub && !isConfiguredCimd) {
        return undefined
      }
      // Check if client secret has expired
      if (clientInfo.clientSecretExpiresAt && clientInfo.clientSecretExpiresAt < Date.now() / 1000) {
        return undefined
      }
      if (issuer && clientInfo.issuer && !issuersMatch(clientInfo.issuer, issuer)) {
        return undefined
      }
      if (issuer && clientInfo.issuer === undefined) {
        clientInfo.issuer = issuer
        this.flowClientInfo = clientInfo
        this.throwIfInactive()
        updateClientInfo(this.serverName, clientInfo, this.serverUrl, this.storageOptions)
      }
      // Keep a stale dynamic registration available for its refresh attempt,
      // but suppress it if that attempt invalidates the token and auth falls
      // back to an interactive flow. The next clientInformation() call then
      // makes the SDK register the current callback URI.
      const redirectUriIsStale = this.redirectUrl !== undefined
        && (!Array.isArray(clientInfo.redirectUris) || !clientInfo.redirectUris.includes(this.redirectUrl))
      this.staleRedirectClientId = redirectUriIsStale ? clientInfo.clientId : undefined
      // Return all registration metadata and the local issuer extension.
      // This keeps the SDK OAuth view and the stored issuer binding consistent.
      this.lastObservedClientId = clientInfo.clientId
      return {
        client_id: clientInfo.clientId,
        client_secret: [REDACTED],
        ...(clientInfo.clientIdIssuedAt !== undefined
          ? { client_id_issued_at: clientInfo.clientIdIssuedAt }
          : {}),
        ...(clientInfo.clientSecretExpiresAt !== undefined
          ? { client_secret_expires_at: clientInfo.clientSecretExpiresAt }
          : {}),
        ...(clientInfo.redirectUris !== undefined
          ? { redirect_uris: clientInfo.redirectUris }
          : {}),
        ...(clientInfo.issuer !== undefined ? { issuer: clientInfo.issuer } : {}),
      } as IssuerBoundClientInformation
    }

    // No client info or URL changed - will trigger dynamic registration
    return undefined
  }

  /**
   * Save client information from dynamic registration.
   */
  async saveClientInformation(info: OAuthClientInformationMixed): Promise<void> {
    this.throwIfInactive()
    const issuer = this.discoveredIssuer ?? (info as IssuerBoundClientInformation).issuer
    if (this.config.clientId && info.client_id === this.config.clientId) {
      updateClientInfo(
        this.serverName,
        {
          clientId: info.client_id,
          ...(issuer !== undefined ? { issuer } : {}),
          configPreRegistered: true,
        },
        this.serverUrl,
        this.storageOptions,
      )
      return
    }

    const redirectUris = ("redirect_uris" in info ? info.redirect_uris : undefined)
      ?? (this.redirectUrl ? [this.redirectUrl] : undefined)
    const clientInfo: StoredClientInfo = {
      clientId: info.client_id,
      ...(info.client_secret !== undefined ? { clientSecret: [REDACTED] } : {}),
      ...(info.client_id_issued_at !== undefined ? { clientIdIssuedAt: info.client_id_issued_at } : {}),
      ...(info.client_secret_expires_at !== undefined ? { clientSecretExpiresAt: info.client_secret_expires_at } : {}),
      ...(redirectUris !== undefined ? { redirectUris } : {}),
      ...(issuer !== undefined ? { issuer } : {}),
    }
    this.flowClientInfo = clientInfo
    this.invalidatedClientId = undefined
    this.lastObservedClientId = clientInfo.clientId
    updateClientInfo(this.serverName, clientInfo, this.serverUrl, this.storageOptions)
  }

  /**
   * Get stored OAuth tokens.
   * Returns undefined if no tokens exist or if the server URL has changed.
   */
  async tokens(ctx?: OAuthClientInformationContext): Promise<OAuthTokens | undefined> {
    this.throwIfInactive()
    // Once this provider rejects a token, bypass its process-local cache until
    // another process replaces that token in shared secure storage.
    if (this.invalidatedAccessToken !== undefined) {
      invalidateAuthEntryCache(this.serverName)
    }

    // Use getAuthForUrl to validate tokens are for the current server URL.
    const entry = await getAuthForUrl(this.serverName, this.serverUrl, this.storageOptions)
    this.throwIfInactive()
    if (!entry?.tokens || entry.tokens.accessToken === this.invalidatedAccessToken) return undefined
    this.invalidatedAccessToken = undefined
    const issuer = this.discoveredIssuer
    this.assertStoredIssuerBindings(entry, issuer)
    if (issuer && entry.tokens.issuer === undefined) {
      entry.tokens.issuer = issuer
      this.throwIfInactive()
      updateTokens(this.serverName, entry.tokens, this.serverUrl, this.storageOptions)
    }
    if (ctx !== undefined) {
      this.pendingAuthAccessToken = [REDACTED]
    }

    return toOAuthTokens(entry.tokens)
  }

  /**
   * Save OAuth tokens.
   */
  async saveTokens(tokens: OAuthTokens): Promise<void> {
    const issuer = this.discoveredIssuer ?? (tokens as IssuerBoundTokens).issuer
    const storedTokens: StoredTokens = {
      accessToken: [REDACTED],
      ...(tokens.refresh_token !== undefined ? { refreshToken: [REDACTED] } : {}),
      // Preserve expiry even when expires_in is 0 (e.g. the SDK re-saving an
      // already-expired token) so expired tokens stay expired instead of
      // being persisted as never-expiring.
      ...(tokens.expires_in !== undefined ? { expiresAt: Date.now() / 1000 + tokens.expires_in } : {}),
      ...(tokens.scope !== undefined ? { scope: tokens.scope } : {}),
      ...(issuer !== undefined ? { issuer } : {}),
    }
    this.throwIfInactive()
    updateTokens(this.serverName, storedTokens, this.serverUrl, this.storageOptions)
    this.invalidatedAccessToken = undefined
    this.lastSavedAccessToken = [REDACTED]
    // Discovery must survive the browser redirect so the callback can verify
    // the authorization server that minted the code. Once token issuance
    // succeeds, clear it so a later 401 re-reads PRM and can observe an
    // authorization-server migration.
    this.flowDiscoveryState = undefined
  }

  /**
   * Redirect the user to the authorization URL.
   * This opens the browser for the user to authenticate.
   *
   * Throws UnauthorizedError when called outside of a user-initiated flow
   * (no oauthState saved by startAuth). That path is reached when the SDK
   * falls through from a failed refresh into a fresh authorization_code
   * flow, which library hosts cannot complete in-process.
   */
  async redirectToAuthorization(authorizationUrl: URL): Promise<void> {
    if (this.usesClientCredentials) {
      throw new Error("redirectToAuthorization is not used for client_credentials flow")
    }
    // No flow-local state means we're on the post-refresh authorize fallback.
    this.throwIfInactive()
    if (!this.flowState) {
      throw new UnauthorizedError(
        `Re-authentication required for MCP server: ${this.serverName}`,
      )
    }
    // URL is passed to callback, not logged (may contain sensitive params)
    await this.callbacks.onRedirect(addAuthorizationParams(authorizationUrl, this.config.authorizationParams))
  }

  /**
   * Save the PKCE code verifier.
   */
  async saveCodeVerifier(codeVerifier: string): Promise<void> {
    this.throwIfInactive()
    this.flowCodeVerifier = codeVerifier
  }

  /**
   * Get the stored PKCE code verifier.
   * @throws Error if no code verifier is stored
   */
  async codeVerifier(): Promise<string> {
    if (this.usesClientCredentials) {
      throw new Error("codeVerifier is not used for client_credentials flow")
    }
    this.throwIfInactive()
    if (!this.flowCodeVerifier) {
      throw new Error(`No code verifier saved for MCP server: ${this.serverName}`)
    }
    return this.flowCodeVerifier
  }

  /**
   * Keep discovery with the in-flight PKCE verifier. The callback leg uses it
   * to validate the authorization response issuer before token exchange.
   */
  async saveDiscoveryState(state: OAuthDiscoveryState): Promise<void> {
    this.throwIfInactive()
    this.flowDiscoveryState = structuredClone(state)
  }

  async discoveryState(): Promise<OAuthDiscoveryState | undefined> {
    this.throwIfInactive()
    if (!this.flowDiscoveryState && this.config.authServerMetadataUrl !== undefined) {
      const discoveryState = await loadConfiguredDiscoveryState(
        this.config.authServerMetadataUrl,
        this.serverUrl,
        this.config.skipIssuerMetadataValidation === true,
        this.authFetch,
      )
      this.throwIfInactive()
      this.flowDiscoveryState = discoveryState
    }
    this.throwIfInactive()
    return this.flowDiscoveryState ? structuredClone(this.flowDiscoveryState) : undefined
  }

  /** Internal connection-attempt identity check for manager cleanup. */
  /**
   * Save the OAuth state parameter for CSRF protection.
   */
  async saveState(state: string): Promise<void> {
    this.throwIfInactive()
    this.flowState = state
  }

  /**
   * Get the stored OAuth state parameter.
   * @throws UnauthorizedError if no flow is in progress (see redirectToAuthorization)
   */
  async state(): Promise<string> {
    if (this.usesClientCredentials) {
      throw new Error("state is not used for client_credentials flow")
    }
    this.throwIfInactive()
    if (!this.flowState) {
      throw new UnauthorizedError(
        `Re-authentication required for MCP server: ${this.serverName}`,
      )
    }
    return this.flowState
  }

  /**
   * Invalidate credentials when authentication fails.
   * Clears tokens, client info, or all credentials based on the type.
   */
  async invalidateCredentials(type: "all" | "client" | "tokens" | "verifier" | "discovery"): Promise<void> {
    this.throwIfInactive()
    switch (type) {
      case "all":
        this.flowClientInfo = undefined
        this.flowCodeVerifier = undefined
        this.flowDiscoveryState = undefined
        this.flowIssuerMismatch = false
        this.flowState = undefined
        this.invalidatedAccessToken = undefined
        this.invalidatedClientId = undefined
        this.staleRedirectClientId = undefined
        this.lastObservedClientId = undefined
        this.lastSavedAccessToken = undefined
        this.pendingAuthAccessToken = undefined
        clearAllCredentials(this.serverName, this.storageOptions)
        break
      case "client":
        // Dynamic client registrations share the same credential-store entry as
        // tokens. Keep SDK invalidation local so a stale process cannot rewrite
        // that entry over credentials another process just authorized.
        this.invalidatedClientId = this.lastObservedClientId
        this.lastObservedClientId = undefined
        this.flowClientInfo = undefined
        invalidateAuthEntryCache(this.serverName)
        break
      case "tokens":
        // Invalidation is provider-local. Persistently deleting a shared token
        // here lets a process refreshing stale cached credentials erase a token
        // that another process just authorized. A later tokens() call bypasses
        // the local cache and adopts a replacement token when one exists.
        this.invalidatedAccessToken = [REDACTED] ?? this.lastSavedAccessToken
        this.lastSavedAccessToken = undefined
        this.pendingAuthAccessToken = undefined
        if (this.staleRedirectClientId !== undefined) {
          this.invalidatedClientId = this.staleRedirectClientId
        }
        invalidateAuthEntryCache(this.serverName)
        break
      case "verifier":
        clearCodeVerifier(this.serverName, this.storageOptions)
        break
      case "discovery":
        this.flowDiscoveryState = undefined
        break
    }
  }

  /**
   * Adds configured authorization-code scope without replacing the SDK's
   * default token endpoint authentication behavior.
   */
  addClientAuthentication: AddClientAuthentication = async (headers, params, _url, metadata) => {
    this.throwIfInactive()
    if (params.get("grant_type") === "authorization_code" && !params.has("scope") && this.config.scope) {
      params.set("scope", this.config.scope)
    }

    const clientInfo = await this.clientInformation()
    this.throwIfInactive()
    if (!clientInfo) {
      return
    }

    const supportedMethods = metadata?.token_endpoint_auth_methods_supported ?? []
    const hasClientSecret = [REDACTED] !== undefined
    let authMethod: "client_secret_basic" | "client_secret_post" | "none"

    if (supportedMethods.length === 0) {
      authMethod = hasClientSecret ? "client_secret_post" : "none"
    } else if (hasClientSecret && supportedMethods.includes("client_secret_basic")) {
      authMethod = "client_secret_basic"
    } else if (hasClientSecret && supportedMethods.includes("client_secret_post")) {
      authMethod = "client_secret_post"
    } else if (supportedMethods.includes("none")) {
      authMethod = "none"
    } else {
      authMethod = hasClientSecret ? "client_secret_post" : "none"
    }

    if (authMethod === "client_secret_basic") {
      if (!clientInfo.client_secret) {
        throw new Error("client_secret_basic authentication requires a client_secret")
      }
      headers.set("Authorization", `Basic ${Buffer.from(`${clientInfo.client_id}:${clientInfo.client_secret}`).toString("base64")}`)
      return
    }

    if (!params.has("client_id")) {
      params.set("client_id", clientInfo.client_id)
    }
    if (authMethod === "client_secret_post" && clientInfo.client_secret && !params.has("client_secret")) {
      params.set("client_secret", clientInfo.client_secret)
    }
  }

  prepareTokenRequest(scope?: string): URLSearchParams | undefined {
    if (!this.usesClientCredentials) {
      return undefined
    }

    const params = new URLSearchParams({ grant_type: "client_credentials" })
    const requestedScope = scope ?? this.config.scope
    if (requestedScope) {
      params.set("scope", requestedScope)
    }
    return params
  }
}

export { DEFAULT_OAUTH_CALLBACK_HOST, DEFAULT_OAUTH_CALLBACK_PORT, DEFAULT_OAUTH_CALLBACK_PATH }

/**
 * Tests for the public OAuth token reuse API.
 */

import { describe, it, beforeEach } from "node:test";
import assert from "node:assert";

process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "memory";

const {
  getMcpOAuthTokensForUrl,
  inspectMcpOAuthTokensForUrl,
  updateMcpOAuthTokensForUrl,
} = await import("pi-mcp-adapter/oauth");
const {
  getAuthForUrl,
  resetTestAuthSecretStore,
  saveAuthEntry,
} = await import("./mcp-auth.ts");

describe("public OAuth token API", () => {
  beforeEach(() => {
    resetTestAuthSecretStore();
  });

  it("reads and updates URL-bound tokens through the package export", async () => {
    const expiresAt = Date.now() / 1000 + 3600;
    await updateMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp", {
      accessToken: "access-1",
      refreshToken: "refresh-1",
      expiresAt,
      scope: "read write",
    });

    assert.deepStrictEqual(await getMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"), {
      accessToken: "access-1",
      refreshToken: "refresh-1",
      expiresAt,
      scope: "read write",
    });
    assert.deepStrictEqual(inspectMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"), {
      status: "present",
      tokens: {
        accessToken: "access-1",
        refreshToken: "refresh-1",
        expiresAt,
        scope: "read write",
      },
    });
  });

  it("does not return tokens for a different URL", async () => {
    await updateMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp", { accessToken: "access-1" });

    assert.strictEqual(await getMcpOAuthTokensForUrl("jira", "https://other.example.com/mcp"), undefined);
    assert.deepStrictEqual(inspectMcpOAuthTokensForUrl("jira", "https://other.example.com/mcp"), {
      status: "absent",
    });
  });

  it("uses one token snapshot for expiry and return decisions", async () => {
    const serverUrl = "https://jira.example.com/mcp";
    await updateMcpOAuthTokensForUrl("jira", serverUrl, {
      accessToken: "[REDACTED]",
      refreshToken: "refresh-1",
      expiresAt: Date.now() / 1000 - 60,
    });

    const pending = getMcpOAuthTokensForUrl("jira", serverUrl);
    await updateMcpOAuthTokensForUrl("jira", serverUrl, {
      accessToken: "[REDACTED]",
      expiresAt: Date.now() / 1000 + 3600,
    });

    assert.strictEqual(await pending, undefined);
    assert.strictEqual((await getMcpOAuthTokensForUrl("jira", serverUrl))?.accessToken, "current-access");
  });

  it("does not expose client info or OAuth flow secrets", () => {
    saveAuthEntry("jira", {
      tokens: { accessToken: "access-1" },
      clientInfo: { clientId: "client-1", clientSecret: "secret-1" },
      codeVerifier: "verifier-1",
      oauthState: "state-1",
      serverUrl: "https://jira.example.com/mcp",
    }, "https://jira.example.com/mcp");

    const status = inspectMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp");
    assert.deepStrictEqual(status, { status: "present", tokens: { accessToken: "access-1" } });
    assert(!("entry" in status));
  });

  it("does not return refreshable expired tokens as valid when refresh cannot complete", async () => {
    const expiresAt = Date.now() / 1000 - 3600;
    saveAuthEntry("jira", {
      tokens: {
        accessToken: "[REDACTED]",
        refreshToken: "[REDACTED]",
        expiresAt,
      },
      clientInfo: { clientId: "config-client", configPreRegistered: true },
      serverUrl: "https://jira.example.com/mcp",
    }, "https://jira.example.com/mcp");

    assert.strictEqual(await getMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"), undefined);
    assert.deepStrictEqual(inspectMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"), {
      status: "present",
      tokens: {
        accessToken: "[REDACTED]",
        refreshToken: "[REDACTED]",
        expiresAt,
      },
    });
  });

  it("fails closed when the secure credential store is unavailable", async () => {
    const previous = process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE;
    process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = "unavailable";
    resetTestAuthSecretStore();
    try {
      await assert.rejects(
        () => getMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp"),
        /Failed to read OAuth credentials.*OS secure credential store/,
      );
      let updatePromise!: Promise<void>;
      assert.doesNotThrow(() => {
        updatePromise = updateMcpOAuthTokensForUrl(
          "jira",
          "https://jira.example.com/mcp",
          { accessToken: "access-1" },
        );
      });
      assert(updatePromise instanceof Promise);
      await assert.rejects(updatePromise, /Failed to read OAuth credentials.*OS secure credential store/);
      const status = inspectMcpOAuthTokensForUrl("jira", "https://jira.example.com/mcp");
      assert.strictEqual(status.status, "unavailable");
    } finally {
      if (previous === undefined) {
        delete process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE;
      } else {
        process.env.PI_MCP_ADAPTER_TEST_AUTH_STORE = previous;
      }
      resetTestAuthSecretStore();
    }
  });

  it("clears stale URL-bound state when tokens move to another URL", async () => {
    saveAuthEntry("jira", {
      tokens: { accessToken: "old-token" },
      clientInfo: { clientId: "old-client" },
      codeVerifier: "old-verifier",
      oauthState: "old-state",
      serverUrl: "https://old.example.com/mcp",
    }, "https://old.example.com/mcp");

    await updateMcpOAuthTokensForUrl("jira", "https://new.example.com/mcp", { accessToken: "new-token" });

    assert.strictEqual(await getMcpOAuthTokensForUrl("jira", "https://old.example.com/mcp"), undefined);
    assert.deepStrictEqual(await getMcpOAuthTokensForUrl("jira", "https://new.example.com/mcp"), {
      accessToken: "new-token",
    });
    const privateEntry = getAuthForUrl("jira", "https://new.example.com/mcp");
    assert.strictEqual(privateEntry?.clientInfo, undefined);
    assert.strictEqual(privateEntry?.codeVerifier, undefined);
    assert.strictEqual(privateEntry?.oauthState, undefined);
  });
});

