          tools: [{ name: "ambient_tool", inputSchema: { type: "object" } }],
          resources: [],
          cachedAt: Date.now(),
        },
      },
    };

    expect(resolveDirectTools({ mcpServers: { shared: programmaticDefinition } }, cache, "server")).toEqual([]);
  });
});

